const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=k=>{try{return JSON.parse(window.fixiverseStorage.getItem(k)||'null');}catch{return null;}};
function dashboard(){const oldRoot=document.querySelector('#app'),keep=!!oldRoot.querySelector('.tutor-detail'),oldY=scrollY,api=window.fixiverseProfiles,learners=api.list(),active=learners.find(p=>p.id===api.active()),f=parse('fixiverse-foundry-v1'),p=parse('fixiverse-pattern-v1');const signals=window.fixiverseSignals(f,p),visits=parse('fixiverse-investigations-v1')||[],patternVisits=parse('fixiverse-pattern-history-v1')||[];document.title='Fixiverse · Tutor workspace';const root=document.querySelector('#app');const prefs=parse('fixiverse-access-v1')||{};root.className='tutor-app storybook-tutor'+(prefs.large?' large':'')+(prefs.motion?' reduced':'');root.innerHTML=`<header><div class="brand">fixiverse <span class="workspace-label">TUTOR WORKSPACE</span></div><button class="quiet" data-tutor="lesson">Open learner workshop ↗</button></header><main id="main" class="tutor-shell"><aside class="tutor-sidebar"><div class="eyebrow">YOUR LEARNERS</div><div class="learner-list">${learners.map(l=>`<button data-tutor="select" data-id="${esc(l.id)}" class="learner-row ${l.id===active.id?'current':''}" ${l.id===active.id?'aria-current="true"':''}><span class="learner-avatar" aria-hidden="true">${esc(l.alias[0].toUpperCase())}</span>${esc(l.alias)}</button>`).join('')}</div><details class="learner-management" ${matchMedia('(min-width:801px)').matches?'open':''}><summary>Manage learners</summary><form id="add-learner"><label for="learner-alias">Add a learner nickname</label><input id="learner-alias" name="alias" maxlength="40" required placeholder="e.g. Bluebird" autocomplete="off"><button class="btn" type="submit">Add learner</button><p id="profile-error" role="status"></p></form><details class="rename-learner"><summary>Rename selected learner</summary><form id="rename-learner"><label for="rename-alias">Nickname</label><input id="rename-alias" name="alias" maxlength="40" required value="${esc(active.alias)}"><button class="quiet" type="submit">Save nickname</button></form></details><p class="tutor-local">${api.memoryOnly()?'Storage unavailable. This visit will not survive a reload.':'Saved only in this browser.'}<br>Nicknames are enough. This view has no sign-in or access lock.</p><button class="quiet" data-tutor="export">Download learner record ↓</button><button class="quiet" data-recovery="open">Back up / restore workspace ↗</button></details></aside><section class="tutor-detail"><div class="eyebrow">LEARNING, WITH CONTEXT</div><div class="tutor-title"><div><h1 tabindex="-1" id="screen-title">${esc(active.alias)}</h1><p>Choose a learner, record a session, and plan the next small step.</p></div><button class="btn" data-session="open">Run a guided session ↗</button></div><section class="tutor-start" aria-label="How to use the tutor workspace"><span class="eyebrow">A SIMPLE SESSION PLAN</span><ol><li><b>Choose a nickname.</b><span>Check the learner shown above before recording.</span></li><li><b>Record before teaching.</b><span>Start a guided session before showing mission examples.</span></li><li><b>Review and continue.</b><span>Use the evidence to choose practice, then export results.</span></li></ol></section><nav class="tutor-jump" aria-label="Tutor workspace sections"><button data-tutor-jump="sessions">Testing session</button><button data-tutor-jump="practice">Next practice</button><button data-tutor-jump="teaching">Teach Pip</button><button data-tutor-jump="evidence">Activity records</button></nav>${window.fixiverseSession?.section()||''}<div class="tutor-metrics"><div><span>Machines repaired</span><b>${Number(!!f?.repairPassed||visits.some(v=>v.ruleRepaired))+Number(!!p?.repaired||patternVisits.length>0||!!parse('fixiverse-grove-repaired-v1'))}<small> / 2</small></b></div><div><span>Archived visits</span><b>${visits.length+patternVisits.length}</b></div><div><span>Latest session support</span><b>${(f?.hints?.length||0)+(p?.hints||0)}<small> hints</small></b></div></div><section class="tutor-section"><div class="section-heading"><h2>Where to focus next</h2><span>Based on recorded actions</span></div><div class="signal-grid">${signals.map((s,i)=>`<article class="signal-card"><div class="signal-top"><span class="mission-number">0${i+1}</span><span class="status-tag">${esc(s.status)}</span></div><h3>${esc(s.mission)}</h3><p class="signal-evidence">${esc(s.evidence)}</p><div class="next-practice"><span class="eyebrow">NEXT PRACTICE</span><p>${esc(s.next)}</p><div class="btn-row"><button class="btn" data-growth="practice" data-mission="${i===0?'fraction':'pattern'}">Practice this next ↗</button><button class="quiet" data-tutor="mission" data-mission="${i===0?'fraction':'pattern'}">Open mission ↗</button></div></div></article>`).join('')}</div></section>${window.fixiverseObservation?.section()||''}${window.fixiverseMentor?.section()||''}${window.fixiverseLab?.section()||''}${window.fixiverseGrowth?.section()||''}<section class="tutor-section"><div class="section-heading"><h2>Activity evidence</h2><span>Latest session in each mission</span></div><div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>Mission / task</th><th>Learner response</th><th>What the task showed</th></tr></thead><tbody>${(f?.experiments||[]).slice(-5).map(e=>`<tr><td>Fraction practice · 1/${e.pair[0]} vs 1/${e.pair[1]}</td><td>${esc(e.choice)}</td><td>${e.choice===e.truth?'Comparison fits':'Revisit comparison'} · expected ${esc(e.truth)}</td></tr>`).join('')}${(f?.checks||[]).filter(c=>c.choice!==null).map(c=>`<tr><td>Fraction check · 1/${c.pair[0]} vs 1/${c.pair[1]}</td><td>${esc(c.choice)}</td><td>${c.choice===c.truth?'Comparison fits':'Revisit comparison'}</td></tr>`).join('')}${(p?.practices||[]).slice(-5).map(a=>`<tr><td>Pattern practice · loop ${esc(a.block.join(" / "))}</td><td>${esc(a.choice)}</td><td>${a.choice===a.expected?"Tile fits":"Revisit loop"} · expected ${esc(a.expected)}</td></tr>`).join('')}${(p?.answers||[]).map((a,i)=>`<tr><td>Pattern check ${i+1} · ${esc((window.fixiversePatternChecks?.[i]?.block||[]).join(" / "))}</td><td>${esc(a.choice)}</td><td>${a.correct?'Tile fits':'Revisit loop'} · ${a.hints} cumulative hints at submission</td></tr>`).join('')}${!f?.experiments?.length&&!f?.checks?.some(c=>c.choice!==null)&&!p?.answers?.length&&!p?.practices?.length?'<tr><td colspan="3">No individual responses stored yet. Practice signals above may still be available.</td></tr>':''}</tbody></table></div></section><section class="tutor-section"><div class="section-heading"><h2>Previous visits</h2><span>Latest 10 from each mission</span></div><div class="visit-list">${visits.slice(0,10).map(v=>`<div><b>Fraction Foundry</b><span>${v.freshCorrect}/${v.freshAnswered} checks · ${v.instructionalHints} hints · tutor help ${esc(v.adultHelp)}</span></div>`).join('')}${patternVisits.slice(0,10).map(v=>`<div><b>Pattern Grove</b><span>${v.correct}/${v.answered} checks · ${v.hints} hints · ${esc(v.at)}</span></div>`).join('')}${!visits.length&&!patternVisits.length?'<p>Finished visits will appear here.</p>':''}</div></section><p class="tutor-caveat">A pause or missed answer is a place to investigate, not a diagnosis. These are practice suggestions, not measured mastery. Unreported adult help is unknown; repeated Grove checks are not new transfer evidence.</p></section></main>`;for(const [key,title] of Object.entries({sessions:'Run a testing session',practice:'Where to focus next',teaching:'When the learner becomes the teacher',evidence:'Activity evidence'})){const section=[...root.querySelectorAll('.tutor-section')].find(el=>el.querySelector('h2')?.textContent===title);if(section)section.id='tutor-'+key;}if(keep){scrollTo(0,oldY);}else{document.querySelector('#screen-title').focus({preventScroll:true});window.scrollTo(0,0);if(!prefs.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)root.querySelector('.tutor-detail')?.animate([{opacity:.4,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'ease-out'});}}
window.fixiverseTutor={show:dashboard};
document.addEventListener('click',e=>{const b=e.target.closest('[data-tutor]');if(!b)return;const a=b.dataset.tutor;if(a==='mission'){location.hash='';window.fixiverseLaunch(b.dataset.mission);return;}if(a==='select'){try{window.fixiverseProfiles.select(b.dataset.id);}catch(err){document.querySelector('#profile-error').textContent=err.message;document.querySelector('.learner-management').open=true;}return;}if(a==='lesson'){location.hash='';window.fixiverseHome();return;}if(a==='export'){const api=window.fixiverseProfiles,data={learner:api.list().find(p=>p.id===api.active()).alias,fractions:parse('fixiverse-foundry-v1'),patterns:parse('fixiverse-pattern-v1'),observations:parse('fixiverse-observations-v1'),guidedSession:parse('fixiverse-guided-session-v1'),fractionTeaching:parse('fixiverse-mentor-fraction-v1'),patternTeaching:parse('fixiverse-mentor-pattern-v1'),fractionRuleLab:parse('fixiverse-rule-lab-fraction-v1'),patternRuleLab:parse('fixiverse-rule-lab-pattern-v1'),fractionCheckins:parse('fixiverse-checkins-fraction-v1'),patternCheckins:parse('fixiverse-checkins-pattern-v1'),fractionPractice:parse('fixiverse-practice-visits-fraction-v1'),patternPractice:parse('fixiverse-practice-visits-pattern-v1'),fractionVisits:parse('fixiverse-investigations-v1'),patternVisits:parse('fixiverse-pattern-history-v1')};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=u;link.download='fixiverse-learner-record.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}});
document.addEventListener('submit',e=>{if(e.target.id==='rename-learner'){e.preventDefault();try{window.fixiverseProfiles.rename(new FormData(e.target).get('alias'));dashboard();const management=document.querySelector('.learner-management');if(management)management.open=true;const details=document.querySelector('.rename-learner');if(details)details.open=true;document.querySelector('#rename-learner button')?.focus({preventScroll:true});document.querySelector('#announcement').textContent='Learner nickname saved.';}catch(err){document.querySelector('#profile-error').textContent=err.message;}return;}if(e.target.id!=='add-learner')return;e.preventDefault();try{window.fixiverseProfiles.add(new FormData(e.target).get('alias'));}catch(err){document.querySelector('#profile-error').textContent=err.message;}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-tutor-jump]');if(!b)return;const target=document.getElementById('tutor-'+b.dataset.tutorJump);if(!target)return;for(const item of document.querySelectorAll('[data-tutor-jump]'))item.removeAttribute('aria-current');b.setAttribute('aria-current','location');const title=target.querySelector('h2,h3')||target;title.tabIndex=-1;title.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:document.querySelector('#app').classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
